import * as React from 'react';
import { PxcMetaCell } from './PxcMetaCell';

export type PxcProfileMetaGridProps = {
  dueDate: React.ReactNode;
  priority: React.ReactNode;
  categories: React.ReactNode;
  status: React.ReactNode;
  workedTotal?: React.ReactNode;
  workedThisMonth?: React.ReactNode;
  estimatedToday?: React.ReactNode;
  keyPortfolioItems: React.ReactNode;
  url: React.ReactNode;
  showTimeFields?: boolean;
};

/**
 * PXC profile metadata grid — same cell chrome as Portfolio Profile
 * (gray label + #f8f9fa value), Tailwind utilities only.
 */
export default function PxcProfileMetaGrid(
  props: PxcProfileMetaGridProps
): React.ReactElement {
  const showTime = props.showTimeFields !== false;

  return (
    <div className="pxc-profile-meta-grid mb-3 grid w-full min-w-0 grid-cols-1 border border-(--brcolor) md:grid-cols-2 [&_.ms-DatePicker]:w-full [&_.ms-TextField-fieldGroup]:!border-0 [&_.ms-TextField-fieldGroup]:!bg-transparent [&_.ms-TextField-fieldGroup]:!shadow-none [&_input]:!border-0 [&_input]:!bg-transparent [&_input]:!shadow-none [&_input]:!outline-none">
      <PxcMetaCell label="Due Date">{props.dueDate}</PxcMetaCell>
      {showTime ? (
        <PxcMetaCell label="Worked Total" lastInRow>
          {props.workedTotal}
        </PxcMetaCell>
      ) : (
        <PxcMetaCell label="Key Portfolio Items" lastInRow>
          {props.keyPortfolioItems}
        </PxcMetaCell>
      )}

      <PxcMetaCell label="Priority">{props.priority}</PxcMetaCell>
      {showTime ? (
        <PxcMetaCell label="Worked this Month" lastInRow>
          {props.workedThisMonth}
        </PxcMetaCell>
      ) : (
        <div className="hidden md:block" />
      )}

      <PxcMetaCell label="Categories">{props.categories}</PxcMetaCell>
      {showTime ? (
        <PxcMetaCell label="Estimated Today" lastInRow>
          {props.estimatedToday}
        </PxcMetaCell>
      ) : (
        <div className="hidden md:block" />
      )}

      <PxcMetaCell label="Status">{props.status}</PxcMetaCell>
      {showTime ? (
        <PxcMetaCell label="Key Portfolio Items" lastInRow>
          {props.keyPortfolioItems}
        </PxcMetaCell>
      ) : (
        <div className="hidden md:block" />
      )}

      <div className="md:col-span-2">
        <PxcMetaCell label="Url" fullWidth lastInRow>
          {props.url}
        </PxcMetaCell>
      </div>
    </div>
  );
}

