import * as React from 'react';

export type PxcProfileHeaderProps = {
  itemType?: string;
  structureId?: string;
  title?: string;
  onEdit?: () => void;
  actions?: React.ReactNode;
};

/** Title row matching Portfolio Profile (Tailwind utilities only). */
export default function PxcProfileHeader(
  props: PxcProfileHeaderProps
): React.ReactElement {
  const { itemType, structureId, title, onEdit, actions } = props;
  const letter =
    itemType === 'Sprint' ? 'X' : (itemType?.charAt(0) || 'P').toUpperCase();

  return (
    <div className="mb-3 flex w-full min-w-0 max-w-full flex-wrap items-center justify-between gap-3 border-b border-[#e5e5e5] pb-3">
      <h2 className="hhhh-page-title m-0 flex min-w-0 flex-1 items-center gap-2 text-[24px] font-normal leading-tight text-(--SiteColor)">
        <span
          title={itemType}
          className="inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-(--SiteColor) text-[14px] leading-6 !text-white"
        >
          {letter}
        </span>
        <span className="min-w-0 truncate">
          {structureId ? `${structureId} - ` : ''}
          {title || ''}
        </span>
        {onEdit ? (
          <span
            title="Edit Project"
            role="button"
            tabIndex={0}
            className="svg__iconbox svg__icon--edit inline-block h-6 w-6 shrink-0 cursor-pointer"
            onClick={onEdit}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onEdit();
              }
            }}
          />
        ) : null}
      </h2>
      {actions ? (
        <div className="flex shrink-0 flex-wrap items-center gap-2">{actions}</div>
      ) : null}
    </div>
  );
}

