import * as React from 'react';

export type PxcProfileShellProps = {
  breadcrumb?: React.ReactNode;
  main: React.ReactNode;
  sidebar?: React.ReactNode;
  below?: React.ReactNode;
};

/**
 * Full-width PXC profile page shell (Portfolio Profile layout pattern).
 * Inline Tailwind only — no legacy dashboard / Bootstrap class names.
 */
export default function PxcProfileShell(
  props: PxcProfileShellProps
): React.ReactElement {
  return (
    <div className="w-full min-w-0 max-w-full overflow-x-hidden bg-white px-2 pb-4 font-[Segoe_UI,Tahoma,Geneva,Verdana,sans-serif] text-[14px] text-[#333]">
      {props.breadcrumb}
      <section className="w-full min-w-0 max-w-full overflow-x-hidden">
        <div className="flex w-full min-w-0 max-w-full flex-col gap-4 lg:flex-row lg:flex-nowrap lg:items-start">
          <div className="min-w-0 max-w-full flex-1 basis-0 overflow-hidden bg-white">
            {props.main}
          </div>
          {props.sidebar ? (
            <aside className="relative w-full min-w-0 max-w-full shrink-0 overflow-x-hidden lg:w-[28%] lg:max-w-[28%]">
              <div className="flex w-full min-w-0 max-w-full flex-col gap-3">
                {props.sidebar}
              </div>
            </aside>
          ) : null}
        </div>
      </section>
      {props.below ? (
        <section className="mt-4 w-full min-w-0 max-w-full overflow-x-hidden">{props.below}</section>
      ) : null}
    </div>
  );
}

