                    key: "overview",
                    onClick: () => goHomeSpa(history, "/project-overview"),
                    label: "PXC Management Overview",
                  },
                  ...(Masterdata?.Item_x0020_Type == "Cycle" && Masterdata?.Parent?.Title
                    ? [
                      {
                        key: "cycle-grandparent",
                        content: (
                          <span className="inline-flex max-w-full items-center bg-(--bge9e9) px-2 py-1 text-sm leading-5 text-(--SiteColor)">
                            <PxcProfileNavLink
                              projectRow={getPxcSeed(Masterdata?.Parent?.Parent?.Id) || Masterdata?.Parent?.Parent}
                              projectId={Masterdata?.Parent?.Parent?.Id}
                              className="truncate text-(--SiteColor) no-underline hover:underline"
                            >
                              {Masterdata?.Parent?.Parent?.PortfolioStructureID?.split("-")?.pop()}{" "}
                              {Masterdata?.Parent?.Parent?.Title}
                            </PxcProfileNavLink>
                          </span>
                        ),
                      },
                      {
                        key: "cycle-parent",
                        content: (
                          <span className="inline-flex max-w-full items-center bg-(--bge9e9) px-2 py-1 text-sm leading-5 text-(--SiteColor)">
                            <PxcProfileNavLink
                              projectRow={getPxcSeed(Masterdata?.Parent?.Id) || Masterdata?.Parent}
                              projectId={Masterdata?.Parent?.Id}
                              className="truncate text-(--SiteColor) no-underline hover:underline"
                            >
                              {Masterdata?.Parent?.PortfolioStructureID?.split("-")?.pop()}{" "}
                              {Masterdata?.Parent?.Title}
                            </PxcProfileNavLink>
                          </span>
                        ),
                      },
                    ]
                    : []),
                  ...(Masterdata?.Item_x0020_Type == "Sprint" && Masterdata?.Parent?.Title
                    ? [
                      {
                        key: "sprint-parent",
                        content: (
                          <span className="inline-flex max-w-full items-center bg-(--bge9e9) px-2 py-1 text-sm leading-5 text-(--SiteColor)">
                            <PxcProfileNavLink
                              projectRow={getPxcSeed(Masterdata?.Parent?.Id) || Masterdata?.Parent}
                              projectId={Masterdata?.Parent?.Id}
                              className="truncate text-(--SiteColor) no-underline hover:underline"
                            >
                              {Masterdata?.Parent?.PortfolioStructureID?.split("-")?.pop()}{" "}
                              {Masterdata?.Parent?.Title}
                            </PxcProfileNavLink>
                          </span>
                        ),
                      },
                    ]
                    : []),
                  {
                    key: "current",
                    active: true,
                    label: `${Masterdata?.PortfolioStructureID?.split("-")?.pop() || ""} ${Masterdata?.Title || ""}`.trim(),
                  },
                ]}
                actions={
                  <>
                    <a
                      className="inline-flex cursor-pointer whitespace-nowrap text-sm text-(--SiteColor) no-underline hover:underline"
                      href={`${AllListId?.siteUrl || props?.siteUrl}/SitePages/PX-Profile.aspx?ProjectId=${Masterdata?.Id || projectId || QueryId}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      data-interception="off"
                      data-spa-external="true"
                      onClick={(e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        openInNewBrowserTab(
                          `${AllListId?.siteUrl || props?.siteUrl}/SitePages/PX-Profile.aspx?ProjectId=${Masterdata?.Id || projectId || QueryId}`
                        );
                      }}
                    >
                      Old Project Profile
                    </a>
                    <a
                      title="Reload All PXCs"
                      className="inline-flex cursor-pointer items-center"
                      onClick={() => clearAllPXCs()}
                    >
                      <span className="svg__iconbox svg__icon--refresh" />
                    </a>
                    <a
                      title="Reload All Tasks"
                      className="inline-flex cursor-pointer items-center"
                      onClick={() => clearAllTasks()}
                    >
                      <span className="svg__iconbox svg__icon--refresh" />
                    </a>
                  </>
                }
              />
            ) : null}
            main={
              <>
                {Masterdata?.Id != undefined && (
                  <PxcProfileHeader
                    itemType={Masterdata?.Item_x0020_Type}
                    structureId={Masterdata?.PortfolioStructureID}
                    title={Masterdata?.Title}
                    onEdit={() => EditComponentPopup(Masterdata)}
                    actions={
                      <div className="flex items-center gap-2">
                        {(workingTodayTasks.length > 0 || PXTasks.length > 0 || AllReleventDoc.length > 0 || Masterdata?.Id != undefined) && (
                          <ExportAllInformation
                            isPXCExport={true}
                            props={Masterdata}
                            workingTodayTasks={workingTodayTasks}
                            allTasks={PXTasks}
                            relevantDocs={AllReleventDoc}
                            SubItemDocs={SubItemDocs}
                            AllListId={AllListId}
                            TeamComposition={TeamComposition}
                            allTableData={allTableData?.length > 0 ? allTableData : ProjectTableData}
                            selectedExportItems={selectedExportItems}
                            setAllPageLoader={setAllPageLoader}
                            allTimeEntryData={AllTimeEntry}
                            teamsChatData={teamsChatData}
                            allTableColumns={allTableColumns?.length > 0 ? allTableColumns : column2}
                            totalTime={totalTime}
                            buttonClassName="bg-white text-[#212529] border border-[#bdbdbd] px-3 py-[6px] text-sm hover:bg-[#f8f9fa] inline-flex items-center gap-1 font-medium cursor-pointer rounded-none"
                          />
                        )}
                        {projectId && AllSitesAllTasks?.length > 0 && (
                          <TagTaskToProjectPopup
                            projectItem={Masterdata}
                            masterTaskData={CSFdata}
                            AllUser={AllUser}
                            siteConfig={siteConfig}
                            className="ml-2"
                            projectId={projectId}
                            AllListId={AllListId}
                            callBack={tagAndCreateCallBack}

