{Masterdata?.Id != undefined && (
  <PxcProfileMetaGrid
    showTimeFields={showTimeEntryIcon}
    dueDate={
      <span className="portfolio-date-field inline-flex w-full min-w-0">
        <InlineEditingcolumns
          AllListId={AllListId}
          callBack={inlineCallBackMasterTask}
          columnName="DueDate"
          item={Masterdata}
          TaskUsers={AllUser}
          pageName="ProjectManagmentMaster"
        />
      </span>
    }
    priority={
      <span className="inline-flex w-full min-w-0 items-center justify-between gap-1 [&_.pancil-icons]:ml-auto [&_.svg__icon--editBox]:ml-auto [&_.svg__iconbox]:ml-auto">
        <InlineEditingcolumns
          mypriority={true}
          AllListId={AllListId}
          callBack={inlineCallBackMasterTask}
          columnName="Priority"
          item={Masterdata}
          TaskUsers={AllUser}
          pageName="ProjectManagmentMaster"
        />
      </span>
    }
    categories={
      <span className="min-w-0 flex-1 truncate" title={Masterdata?.Categories}>
        {Masterdata?.Categories}
      </span>
    }
    status={
      <span className="inline-flex w-full min-w-0 items-center justify-between gap-1 [&_.pancil-icons]:ml-auto [&_.svg__icon--editBox]:ml-auto [&_.svg__iconbox]:ml-auto">
        <InlineEditingcolumns
          AllListId={AllListId}
          callBack={inlineCallBackMasterTask}
          columnName="PercentComplete"
          item={Masterdata}
          TaskUsers={AllUser}
          pageName="ProjectManagmentMaster"
        />
      </span>
    }
    workedTotal={
      totalTime != undefined && totalTime != 0 ? (
        <span title="Worked Total">{`${totalTime.toFixed(2)} hrs`}</span>
      ) : null
    }
    workedThisMonth={
      monthTotalTime != undefined && monthTotalTime != 0 ? (
        <span title="Worked this Month">{`${monthTotalTime.toFixed(2)} hrs`}</span>
      ) : null
    }
    estimatedToday={
      todayTotalTime != undefined && todayTotalTime != 0 ? (
        <span title="Estimated Today">{`${todayTotalTime.toFixed(2)} hrs`}</span>
      ) : null
    }
    keyPortfolioItems={
      <>
        {openServiceComponent ? (
          <ServiceComponentPortfolioPopup
            props={Masterdata?.taggedPortfolios}
            Portfolios={Masterdata.taggedPortfolios}
            Relevant={TaskTaggedPortfolios}
            Suggested={suggestedPortfolioItems}
            Dynamic={AllListId}
            ComponentType={portfolioType}
            Call={ComponentServicePopupCallBack}
            selectionType="Multi"
            portfolioTiles={Masterdata?.taggedPortfolios}
            pageName="projectManagement"
          />
        ) : null}
        <span className="min-w-0 flex-1 truncate" title={keyPortFolioTitle}>
          {smartPortfoliosData.length > 0 &&
            smartPortfoliosData.map((component: any, index: any) => (
              <span key={index}>
                <a
                  className="text-(--SiteColor) no-underline hover:underline"
                  href={`${AllListId.siteUrl}/SitePages/Task-Management.aspx?taskId=${component?.Id}#/portfolio-profile`}
                  target="_blank"
                  data-interception="off"
                >
                  {`${component?.PortfolioStructureID} ${component?.Title}`}
                </a>
                {index < smartPortfoliosData.length - 1 ? "; " : ""}
              </span>
            ))}
        </span>
        <a
          className="ml-auto inline-flex shrink-0 cursor-pointer items-center"
          onClick={() => setopenServiceComponent(true)}
        >
          <span className="svg__iconbox svg__icon--editBox"></span>
        </a>
      </>
    }
    url={
      <a
        className="min-w-0 break-all text-(--SiteColor) no-underline hover:underline"
        target="_blank"
        data-interception="off"
        href={Masterdata?.ComponentLink?.Url != undefined ? Masterdata?.ComponentLink?.Url : ""}
      >
        {Masterdata?.ComponentLink?.Url != undefined ? Masterdata?.ComponentLink?.Url : ""}
      </a>
    }
  />
)}

{Masterdata?.Body && /\S/.test(Masterdata.Body.replace(/<[^>]*>/g, "")) ? (
  <PxcProfileAccordion title={`Description (${Masterdata.Body.replace(/<[^>]*>/g, "").length})`}>
    <div className="break-words text-sm text-[#333]" dangerouslySetInnerHTML={{ __html: Masterdata?.Body }} />
  </PxcProfileAccordion>
) : null}

{Masterdata?.Background && /\S/.test(Masterdata.Background.replace(/<[^>]*>/g, "")) ? (
  <PxcProfileAccordion title={`Background (${Masterdata.Background.replace(/<[^>]*>/g, "").length})`}>
    <div className="break-words text-sm text-[#333]" dangerouslySetInnerHTML={{ __html: Masterdata?.Background }} />
  </PxcProfileAccordion>
) : null}

{Masterdata?.Idea && /\S/.test(Masterdata.Idea.replace(/<[^>]*>/g, "")) ? (
  <PxcProfileAccordion title={`Idea (${Masterdata.Idea.replace(/<[^>]*>/g, "").length})`}>
    <div className="break-words text-sm text-[#333]" dangerouslySetInnerHTML={{ __html: Masterdata?.Idea }} />
  </PxcProfileAccordion>
) : null}

{Masterdata?.Deliverables && /\S/.test(Masterdata.Deliverables.replace(/<[^>]*>/g, "")) ? (
  <PxcProfileAccordion title={`Deliverables (${Masterdata.Deliverables.replace(/<[^>]*>/g, "").length})`}>
    <div className="break-words text-sm text-[#333]" dangerouslySetInnerHTML={{ __html: Masterdata?.Deliverables }} />
  </PxcProfileAccordion>
) : null}

<PxcProfileAccordion
  empty={TeamComposition.length === 0}
  title={
    TeamComposition?.length === 0 ? (
      "Team Composition"
    ) : (
      <span className="inline-flex min-w-0 flex-nowrap items-center gap-2 [&_.w-full]:!w-auto [&_div.flex]:!inline-flex">
        <span className="shrink-0 whitespace-nowrap">Team Composition</span>
        <ShowTeamCompositionMembers AllListId={AllListId} TeamMembers={fullTeamList} />
      </span>
    )
  }
  summaryExtra={
    <>
      {TeamComposition?.length === 0 ? <span className="text-[#666]">No Data</span> : null}
      <a
        className="cursor-pointer whitespace-nowrap font-normal text-(--SiteColor) no-underline hover:underline"
        onClick={() => setTeamCompositionPanel(true)}
      >
        Team Composition
      </a>
      {(Masterdata?.Item_x0020_Type === "Project" ||
        Masterdata?.Item_x0020_Type === "Sprint" ||
        Masterdata?.Item_x0020_Type === "Cycle") && (
          <a className="inline-flex cursor-pointer" onClick={() => openTeamsPopup()}>
            <span title="Create Teams Group" className="svg__iconbox svg__icon--team"></span>
          </a>
        )}
      <Tooltips ComponentId={14642} />
    </>
  }
>
  {TeamComposition.length > 0 ? (
    <div className="w-full min-w-0 max-w-full overflow-hidden [&_[role=region]]:!min-h-[70px] [&_[role=region]]:!h-[20px]">
      <GlobalCommanTable
        maxWrapperHeight={true}
        AllListId={AllListId}
        columns={teamCompositionColumns}
        data={TeamComposition}
        wrapperHeight="200px"
        callBackData={() => { }}
        showHeader={true}
        setLoaded={setPageLoader}
        hideOpenNewTableIcon={true}
        hideTeamIcon={true}
      />
    </div>
  ) : (
    <div className="w-full py-3 text-center text-sm text-[#666]">No Data Available</div>
  )}
</PxcProfileAccordion>

{showTimeEntryIcon ? (
